			dp[2][y2][0][0][d] += count1[y1]
		}
	}

	// Fill for i from 3 to n
	for i := 3; i <= n; i++ {
		for y_prev := 1; y_prev <= 4; y_prev++ {
			for p := 0; p <= t; p++ {
				for v := 0; v <= t-1; v++ {
					for d_prev := 0; d_prev <= 1; d_prev++ {
						val := dp[i-1][y_prev][p][v][d_prev]
						if val == 0 {
							continue
						}
						for y_new := 1; y_new <= 4; y_new++ {
