								new_p = p + 1
							} else if d_prev == 0 && d_new == 1 {
								// was going down, now going up: valley at i-1
								new_v = v + 1
							}
							if new_p <= t && new_v <= t-1 {
								dp[i][y_new][new_p][new_v][d_new] += val
							}
						}
					}
				}
			}
		}
	}

	// Sum up all states at i=n with p=t and v=t-1
	var result int
	for y := 1; y <= 4; y++ {
		for d := 0; d <= 1; d++ {
			result += dp[n][y][t][t-1][d]
		}
	}

	fmt.Println(result)
