func main() {
	var n, t int
	fmt.Scan(&n, &t)

	// We need to count sequences y1, y2, ..., yn where:
	// - each yi is in {1, 2, 3, 4}
	// - no two consecutive are equal (no horizontal segments)
	// - exactly t local maxima (humps): y[j-1] < y[j] > y[j+1] for j in 2..n-1
	// - exactly t-1 local minima: y[j-1] > y[j] < y[j+1] for j in 2..n-1

	// Use DP: dp[i][last][maxima][minima] = number of ways
	// i: position (1-indexed), last: last y value (1-4), maxima: count of humps so far, minima: count of valleys so far

	// Since n <= 20, t <= 10, and y values are 1-4, we can use a 4D DP.
	// dp[i][last][m][v] where i is from 1 to n, last in 1..4, m in 0..t, v in 0..t-1 (or up to t)

	// Initialize
	dp := make([][][]int, n+1)
	for i := range dp {
		dp[i] = make([][]int, 5) // index 1..4
		for j := range dp[i] {
			dp[i][j] = make([]int, t+1)
		}
	}

	// Base case: i=1, any y1 in 1..4
	for y := 1; y <= 4; y++ {
		dp[1][y][0][0] = 1
	}

	// Transition
	for i := 2; i <= n; i++ {
		for last := 1; last <= 4; last++ {
			for m := 0; m <= t; m++ {
				for v := 0; v <= t-1; v++ { // minima can be at most t-1, but let's allow up to t for safety
					if dp[i-1][last][m][v] == 0 {
						continue
					}
					for next := 1; next <= 4; next++ {
						if next == last {
							continue // no horizontal segments
						}
						// Check if we can form a hump or valley at position i-1
						// We need the previous value to check. But we don't have it in our state.
						// We need to track the previous value as well, or restructure.
					}
				}
			}
		}
	}

	// The above approach doesn't work because we need the previous value to determine if position i-1 is a hump or valley.
	// Let's restructure: dp[i][prev][last][m][v] is too much. Instead, let's use dp[i][last][m][v] but we need to know prev.
	// Actually, we can just iterate and for each step, we know last (which was prev in the previous step).
	// Let me redo: dp[i][last][m][v] where last is y_i.
	// To compute dp[i][last][m][v], we need to sum over all prev != last of dp[i-1][prev][m'][v']
	// and check if position i-1 (which has value prev) is a hump or valley based on the value before prev.
	// But we don't have the value before prev in our state.

	// Better approach: dp[i][prev][last][m][v]
	// i: current position
	// prev: y_{i-1}
	// last: y_i
	// m: number of humps so far (at positions 2..i-1)
	// v: number of valleys so far (at positions 2..i-1)

	// Size: n * 4 * 4 * (t+1) * (t+1) which is 20*4*4*11*11 = 38720, very manageable.

	dp2 := make([][][][]int, n+1)
	for i := range dp2 {
		dp2[i] = make([][][]int, 5)
		for a := range dp2[i] {
			dp2[i][a] = make([][]int, 5)
			for b := range dp2[i][a] {
				dp2[i][a][b] = make([]int, t+1)
			}
		}
	}

	// Base case: i=2, prev=y1, last=y2
	for y1 := 1; y1 <= 4; y1++ {
		for y2 := 1; y2 <= 4; y2++ {
			if y1 == y2 {
				continue
			}
			// At position 1, we can't have a hump or valley (needs neighbors on both sides)
			// So m=0, v=0
			dp2[2][y1][y2][0][0] = 1
		}
	}

	// Transition for i from 3 to n
	for i := 3; i <= n; i++ {
		for prev := 1; prev <= 4; prev++ {
			for last := 1; last <= 4; last++ {
				if prev == last {
					continue
				}
				for m := 0; m <= t; m++ {
					for v := 0; v <= t-1; v++ {
						if dp2[i-1][prev][last][m][v] == 0 {
							continue
						}
						for next := 1; next <= 4; next++ {
							if next == last {
								continue
							}
							// Check if position i-1 (value = last) is a hump or valley
							// Hump: prev < last > next
							// Valley: prev > last < next
							newM := m
							newV := v
							if prev < last && last > next {
								newM++
							} else if prev > last && last < next {
								newV++
							}
							if newM <= t && newV <= t-1 {
								dp2[i][last][next][newM][newV] += dp2[i-1][prev][last][m][v]
							}
						}
					}
				}
			}
		}
	}

	// Sum up all dp2[n][prev][last][t][t-1] for all prev, last
	result := 0
	for prev := 1; prev <= 4; prev++ {
		for last := 1; last <= 4; last++ {
			if prev != last {
				result += dp2[n][prev][last][t][t-1]
			}
		}
	}

	fmt.Println(result)
}
