func main() {
	var n, t int
	fmt.Scan(&n, &t)

	// We need to count sequences y1..yn where:
	// - each yi is in {1,2,3,4}
	// - no two consecutive are equal (no horizontal segments)
	// - exactly t "peaks": j in [2, n-1] such that y[j-1] < y[j] > y[j+1]
	// - exactly t-1 "valleys": j in [2, n-1] such that y[j-1] > y[j] < y[j+1]

	// We'll use dynamic programming.
	// State: position i (1-indexed), last value y[i], previous direction (up/down),
	//        count of peaks so far, count of valleys so far.
	//
	// Actually, let's think about it differently.
	// Let's define the sequence of y values. The "turns" happen at internal points.
	// At each internal point j (2 <= j <= n-1), we can classify it as:
	//   - peak: y[j-1] < y[j] > y[j+1]
	//   - valley: y[j-1] > y[j] < y[j+1]
	//   - neither (monotonic continuation or flat, but flat is not allowed)
	//
	// Since no two consecutive y's are equal, at each internal point j, either:
	//   y[j-1] < y[j] and y[j] < y[j+1]  -> valley
	//   y[j-1] > y[j] and y[j] > y[j+1]  -> peak
	//   y[j-1] < y[j] and y[j] > y[j+1]  -> peak
	//   y[j-1] > y[j] and y[j] < y[j+1]  -> valley
	//
	// Wait, let me re-examine:
	//   If y[j-1] < y[j] and y[j] > y[j+1]: peak
	//   If y[j-1] > y[j] and y[j] < y[j+1]: valley
	//   If y[j-1] < y[j] and y[j] < y[j+1]: neither (going up then up)
	//   If y[j-1] > y[j] and y[j] > y[j+1]: neither (going down then down)
	//
	// So we need to track:
	//   - current position i
	//   - current y value
	//   - previous y value (to determine direction into current point)
	//   - number of peaks so far
	//   - number of valleys so far
	//
	// But we can simplify: at position i, we know y[i-1] and y[i]. 
	// When we add y[i+1], we can determine if position i is a peak or valley.
	//
	// Let's use DP with state: (i, prev, curr, peaks, valleys)
	// where i is the current index (we've placed y[1]..y[i]),
	// prev = y[i-1], curr = y[i], peaks = number of peaks among positions 2..i-1,
	// valleys = number of valleys among positions 2..i-1.
	//
	// When we extend to y[i+1] = next:
	//   - Check curr != next (no horizontal)
	//   - Determine if position i is a peak or valley based on prev, curr, next
	//   - Update peaks/valleys count
	//
	// Base case: i=2, we have y[1] and y[2]. No internal points yet, so peaks=0, valleys=0.
	// Final: i=n, check peaks==t and valleys==t-1.

	// dp[i][prev][curr][peaks][valleys] = count
	// i ranges from 2 to n
	// prev, curr in {1,2,3,4}
	// peaks from 0 to t
	// valleys from 0 to t-1 (but we can allow up to t for safety)

	maxPeaks := t
	maxValleys := t - 1
	if maxValleys < 0 {
		maxValleys = 0
	}

	// dp[prev][curr][peaks][valleys] for current i
	// We'll iterate i from 2 to n

	// Initialize for i=2
	// dp2[prev][curr][0][0] = 1 for all prev != curr
	dp := make([][][][]int, 5)
	for i := range dp {
		dp[i] = make([][][]int, 5)
		for j := range dp[i] {
			dp[i][j] = make([][]int, maxPeaks+1)
			for k := range dp[i][j] {
				dp[i][j][k] = make([]int, maxValleys+1)
			}
		}
	}

	// For i=2: prev=y1, curr=y2, peaks=0, valleys=0
	for prev := 1; prev <= 4; prev++ {
		for curr := 1; curr <= 4; curr++ {
			if prev != curr {
				dp[prev][curr][0][0] = 1
			}
		}
	}

	// Now extend from i=2 to i=n
	// At step i, we have states for position i (with y[i-1]=prev, y[i]=curr)
	// We want to compute states for position i+1

	for i := 2; i < n; i++ {
		// newdp will hold states for position i+1
		newdp := make([][][][]int, 5)
		for a := range newdp {
			newdp[a] = make([][][]int, 5)
			for b := range newdp[a] {
				newdp[a][b] = make([][]int, maxPeaks+1)
				for c := range newdp[a][b] {
					newdp[a][b][c] = make([]int, maxValleys+1)
				}
			}
		}

		for prev := 1; prev <= 4; prev++ {
			for curr := 1; curr <= 4; curr++ {
				for peaks := 0; peaks <= maxPeaks; peaks++ {
					for valleys := 0; valleys <= maxValleys; valleys++ {
						count := dp[prev][curr][peaks][valleys]
						if count == 0 {
							continue
						}
						for next := 1; next <= 4; next++ {
							if curr == next {
								continue // no horizontal
							}
							// Determine if position i is a peak or valley
							newPeaks := peaks
							newValleys := valleys
							if prev < curr && curr > next {
								// peak at position i
								newPeaks++
							} else if prev > curr && curr < next {
								// valley at position i
								newValleys++
							}
							// else: neither, no change

							if newPeaks <= maxPeaks && newValleys <= maxValleys {
								newdp[curr][next][newPeaks][newValleys] += count
							}
						}
					}
				}
			}
		}
		dp = newdp
	}

	// After the loop, dp holds states for position n
	// We need peaks == t and valleys == t-1
	answer := 0
	for prev := 1; prev <= 4; prev++ {
		for curr := 1; curr <= 4; curr++ {
			if t <= maxPeaks && (t-1) <= maxValleys {
				answer += dp[prev][curr][t][t-1]
			}
		}
	}

	fmt.Println(answer)
}
