	// last: the last y value (1..4)
	// peaks: number of peaks so far
	// valleys: number of valleys so far

	// Max peaks and valleys: at most n-2
	// t <= 10, n <= 20

	maxPeaks := t
	maxValleys := t - 1

	// dp[i][last][p][v]
	// i from 0 to n-1
	// last from 1 to 4
	// p from 0 to maxPeaks
	// v from 0 to maxValleys

	// Initialize
	// dp[0][y][0][0] = 1 for y in 1..4
	// But we can't count peaks/valleys until we have at least 3 elements.

	// Let's use a 4D array or map. Since n is small (<=20), we can use a 4D slice.
	// dp[i][last][p][v]
	// i: 0..n-1
	// last: 1..4
	// p: 0..maxPeaks
	// v: 0..maxValleys

	// Create dp table
	// dp[i][last][p][v]
	dp := make([][][][]int, n)
	for i := 0; i < n; i++ {
		dp[i] = make([][][]int, 5) // index 1..4 for last
		for last := 1; last <= 4; last++ {
			dp[i][last] = make([][]int, maxPeaks+1)
			for p := 0; p <= maxPeaks; p++ {
				dp[i][last][p] = make([]int, maxValleys+1)
			}
		}
	}

	// Base case: first element
	for y := 1; y <= 4; y++ {
		dp[0][y][0][0] = 1
	}

	// Fill DP
	for i := 1; i < n; i++ {
		for last := 1; last <= 4; last++ {
			for p := 0; p <= maxPeaks; p++ {
				for v := 0; v <= maxValleys; v++ {
					if dp[i-1][last][p][v] == 0 {
						continue
					}
					for newLast := 1; newLast <= 4; newLast++ {
						if newLast == last {
							continue // no horizontal segments
						}
						newP := p
						newV := v
						if i >= 2 {
							// We can check if position i-1 (0-indexed) is a peak or valley
							// The three consecutive values are: dp[i-2][prev][...], dp[i-1][last][...], newLast
							// But we don't have prev stored. We need to know the previous value.
							// So we need to extend the state to include the previous value.
						}
						// Actually, we need to know the previous value to determine peak/valley.
						// Let's restructure: dp[i][prev][last][p][v]
						// This is getting complex. Let's use a different approach.
					}
				}
			}
		}
	}

	// Let's restart with a cleaner DP that tracks the last two values.
	// dp[i][a][b][p][v] where a = y[i-1], b = y[i], p = peaks so far, v = valleys so far
	// i >= 1

	// Reset
	// We'll use a map or a 5D array.
	// i from 1 to n-1
	// a, b from 1 to 4
	// p from 0 to maxPeaks
	// v from 0 to maxValleys

	// dp[i][a][b][p][v]
	// For i=1: a = y[0], b = y[1]
	// For i>=2: when we add y[i+1] = c, we can check if y[i-1]=a, y[i]=b, y[i+1]=c forms a peak or valley.

	// Let's use a 5D slice.
	// dp[i][a][b][p][v]
	// i: 1..n-1 (we have placed i+1 elements, indices 0..i)
	// a: y[i-1] (1..4)
	// b: y[i] (1..4)
	// p: peaks (0..maxPeaks)
	// v: valleys (0..maxValleys)

	dp2 := make([][][][][]int, n)
	for i := 0; i < n; i++ {
		dp2[i] = make([][][][]int, 5)
		for a := 1; a <= 4; a++ {
			dp2[i][a] = make([][][]int, 5)
			for b := 1; b <= 4; b++ {
				dp2[i][a][b] = make([][]int, maxPeaks+1)
				for p := 0; p <= maxPeaks; p++ {
					dp2[i][a][b][p] = make([]int, maxValleys+1)
				}
			}
		}
	}

	// Base: i=1, a=y[0], b=y[1]
	for a := 1; a <= 4; a++ {
		for b := 1; b <= 4; b++ {
			if a == b {
				continue
			}
			dp2[1][a][b][0][0] = 1
		}
	}

	// Fill for i from 2 to n-1
	for i := 2; i < n; i++ {
		for a := 1; a <= 4; a++ {
			for b := 1; b <= 4; b++ {
				for p := 0; p <= maxPeaks; p++ {
					for v := 0; v <= maxValleys; v++ {
						if dp2[i-1][a][b][p][v] == 0 {
							continue
						}
						for c := 1; c <= 4; c++ {
							if c == b {
								continue // no horizontal
							}
							newP := p
							newV := v
							// Check if b is a peak or valley: a, b, c
							if a < b && b > c {
								// peak
								if p+1 <= maxPeaks {
									newP = p + 1
								} else {
									continue
								}
							} else if a > b && b < c {
								// valley
								if v+1 <= maxValleys {
									newV = v + 1
								} else {
									continue
								}
							}
							// a < b < c or a > b > c: no peak/valley at b
							// a < b == c: not possible since c != b
							// a > b == c: not possible since c != b
							// a == b: not possible since a != b (from previous step)
							// Actually a and b could be equal? No, we ensured a != b in base and transitions.
							// Wait, in the transition from i-1 to i, we have a=y[i-2], b=y[i-1], c=y[i]
							// We check if b is peak/valley based on a, b, c.
							// Then new state is (b, c) for position i.
							dp2[i][b][c][newP][newV] += dp2[i-1][a][b][p][v]
						}
					}
				}
			}
		}
	}

	// Sum up all dp2[n-1][a][b][t][t-1] for all a, b
	result := 0
	for a := 1; a <= 4; a++ {
		for b := 1; b <= 4; b++ {
			if t <= maxPeaks && (t-1) <= maxValleys {
				result += dp2[n-1][a][b][t][t-1]
			}
		}
	}

	fmt.Println(result)
