	// Base case: i=1 (index 0 in 0-based, but let's use 1-based for clarity)
	// Let's use 1-based indexing for i.
	// dp[i][y][h][m][d] where i is 1..n, y is 1..4 (use 0..3 in array), h is 0..t, m is 0..t-1, d is 0..1

	// Initialize for i=1
	for y := 1; y <= 4; y++ {
		dp[1][y-1][0][0][0] = 1 // d=0 dummy
	}

	// Fill for i from 2 to n
	for i := 2; i <= n; i++ {
		for y := 1; y <= 4; y++ {
			for h := 0; h <= t; h++ {
				for m := 0; m <= t-1; m++ {
					for d := 0; d <= 1; d++ {
						if dp[i-1][y-1][h][m][d] == 0 {
							continue
						}
						// Try all previous y'
						for yp := 1; yp <= 4; yp++ {
							if yp == y {
								continue
							}
							// new direction
							var newDir int
							if y > yp {
								newDir = 0 // increasing
							} else {
								newDir = 1 // decreasing
							}
							// Check if position i-1 is internal (i-1 >= 2 and i-1 <= n-1)
							// i-1 is the previous position, which is now being checked as a local max/min
							// i-1 is internal if 2 <= i-1 <= n-1, i.e., 3 <= i <= n
							// Wait, when we are at position i, we're adding y[i]. The point at position i-1 can be checked if i-1 >= 2 and i-1 <= n-1.
							// i-1 >= 2 means i >= 3.
							// i-1 <= n-1 means i <= n.
							// So if i >= 3, position i-1 is internal.

							hp := h
							mp := m
							if i >= 3 {
								// Check if y[i-1] (which is yp) is a local max or min
								// The direction from i-2 to i-1 is d (the stored direction)
								// The direction from i-1 to i is newDir
								if d == 0 && newDir == 1 {
									// local max
									hp = h + 1
								} else if d == 1 && newDir == 0 {
									// local min
									mp = m + 1
								}
							}

							if hp <= t && mp <= t-1 {
								dp[i][y-1][hp][mp][newDir] += dp[i-1][yp-1][h][m][d]
							}
						}
					}
				}
			}
		}
	}

	// Sum up all states at i=n where h==t and m==t-1
	var result int64 = 0
	for y := 1; y <= 4; y++ {
		for d := 0; d <= 1; d++ {
			result += dp[n][y-1][t][t-1][d]
		}
	}

	fmt.Println(result)
}
