func main() {
	var n, t int
	fmt.Scan(&n, &t)

	// We need to count sequences y1..yn where:
	// - each yi in {1,2,3,4}
	// - no two consecutive are equal (no horizontal segment)
	// - exactly t local maxima (humps): indices j in [2, n-1] where y[j-1] < y[j] > y[j+1]
	// - exactly t-1 local minima: indices j in [2, n-1] where y[j-1] > y[j] < y[j+1]

	// We can use DP.
	// State: position i, last value y[i], whether the previous segment was going up or down,
	// and counts of humps and valleys so far.
	// But we need to be careful: a hump/valley is determined at position j when we have y[j-1], y[j], y[j+1].
	// So when we add a new point y[i], we can determine if position i-1 is a hump or valley.

	// Let's define:
	// dp[i][last][prev_dir][humps][valleys]
	// where i is the current position (1-indexed), last is y[i], prev_dir is the direction from y[i-1] to y[i] (1 for up, -1 for down),
	// humps is the count of humps so far (among positions 2..i-1), valleys is the count of valleys so far.

	// Actually, when we are at position i, we have determined the nature of position i-1 (if i >= 3).
	// Let's re-index: let's say we build the sequence from left to right.
	// After placing y[i], we can check if y[i-1] is a hump or valley (for i >= 3, i-1 >= 2).

	// Let's use:
	// dp[i][last][dir][h][v] = number of ways to have a sequence of length i ending with value 'last',
	// where the direction from y[i-1] to y[i] is 'dir' (1=up, -1=down),
	// and we have 'h' humps and 'v' valleys among positions 2..i-1.

	// Base case: i=1, no direction yet. We can handle i=1 separately.
	// For i=1: dp[1][y1][0][0][0] = 1 for y1 in {1,2,3,4}
	// For i=2: dp[2][y2][dir][0][0] = 1 if y1 != y2, dir = sign(y2-y1)

	// Transition from i to i+1:
	// Choose next value next in {1,2,3,4} such that next != last.
	// new_dir = sign(next - last)
	// Check if position i (which is the middle of y[i-1], y[i], y[i+1]=next) is a hump or valley.
	// Position i is a hump if: y[i-1] < y[i] > y[i+1], i.e., prev_dir == 1 (up into i) and new_dir == -1 (down from i)
	// Position i is a valley if: y[i-1] > y[i] < y[i+1], i.e., prev_dir == -1 (down into i) and new_dir == 1 (up from i)

	// So:
	// new_h = h + (1 if prev_dir==1 && new_dir==-1 else 0)
	// new_v = v + (1 if prev_dir==-1 && new_dir==1 else 0)

	// We need final answer: sum over all last, dir, where h == t and v == t-1, for i = n.

	// Dimensions:
	// i: 1..n (n <= 20)
	// last: 1..4
	// dir: -1, 1 (we can use 0 and 1 to index, or just use a map)
	// h: 0..t (t <= 10)
	// v: 0..t-1 (t-1 <= 9)

	// Let's use a 5D array or nested maps. Given small constraints, a 5D slice is fine.
	// dp[i][last][dir_idx][h][v]
	// dir_idx: 0 for dir=-1, 1 for dir=1

	const maxN = 20
	const maxT = 10
	const maxVal = 4

	// dp[i][last][dir_idx][h][v]
	// i from 1 to n
	// last from 1 to 4
	// dir_idx: 0 (down, -1), 1 (up, 1)
	// h from 0 to t
	// v from 0 to t-1

	// Initialize with 0
	dp := make([][][][]int64, maxN+1)
	for i := range dp {
		dp[i] = make([][][]int64, maxVal+1)
		for last := range dp[i] {
			dp[i][last] = make([][]int64, 2)
			for d := range dp[i][last] {
				dp[i][last][d] = make([]int64, maxT+1)
				for h := range dp[i][last][d] {
					dp[i][last][d][h] = make(int64, maxT) // v from 0 to t-1, so size t
				}
			}
		}
	}

	// Base: i=1
	for y1 := 1; y1 <= 4; y1++ {
		// No direction yet, so we can't really use dir. Let's handle i=1 and i=2 separately.
		// Actually, let's start from i=2.
	}

	// Let's do i=1 as a special case and then transition to i=2.
	// For i=1, we just store the value. Let's use a separate array for i=1.
	// Or, we can say for i=1, dir is undefined. Let's just handle the transition from i=1 to i=2 manually.

	// Alternative: start dp at i=2.
	// For i=2: for each y1, y2 with y1 != y2, dir = sign(y2-y1)
	// dp[2][y2][dir_idx][0][0] += 1

	for y1 := 1; y1 <= 4; y1++ {
		for y2 := 1; y2 <= 4; y2++ {
			if y1 == y2 {
				continue
			}
			dir := 1
			if y2 < y1 {
				dir = -1
			}
			dirIdx := 1 // up
			if dir == -1 {
				dirIdx = 0 // down
			}
			dp[2][y2][dirIdx][0][0]++
		}
	}

	// Transition from i to i+1 for i from 2 to n-1
	for i := 2; i < n; i++ {
		for last := 1; last <= 4; last++ {
			for dirIdx := 0; dirIdx < 2; dirIdx++ {
				dir := 1
				if dirIdx == 0 {
					dir = -1
				}
				for h := 0; h <= t; h++ {
					for v := 0; v < t; v++ {
						count := dp[i][last][dirIdx][h][v]
						if count == 0 {
							continue
						}
						for next := 1; next <= 4; next++ {
							if next == last {
								continue
							}
							newDir := 1
							if next < last {
								newDir = -1
							}
							newDirIdx := 1
							if newDir == -1 {
								newDirIdx = 0
							}

							// Check if position i is a hump or valley
							newH := h
							newV := v
							// Position i is a hump if: came up (dir==1) and going down (newDir==-1)
							if dir == 1 && newDir == -1 {
								newH++
							}
							// Position i is a valley if: came down (dir==-1) and going up (newDir==1)
							if dir == -1 && newDir == 1 {
								newV++
							}

							if newH <= t && newV < t {
								dp[i+1][next][newDirIdx][newH][newV] += count
							}
						}
					}
				}
			}
		}
	}

	// Sum up for i=n, where h == t and v == t-1
	var ans int64 = 0
	for last := 1; last <= 4; last++ {
		for dirIdx := 0; dirIdx < 2; dirIdx++ {
			if t <= maxT && t-1 < t {
				ans += dp[n][last][dirIdx][t][t-1]
			}
		}
	}

	fmt.Println(ans)
