	}
	var n, t int
	fmt.Sscanf(parts[0], "%d", &n)
	fmt.Sscanf(parts[1], "%d", &t)

	// y[i] is the y-coordinate at position i (0-indexed), so x = i+1
	// y values are 1..4
	// Conditions:
	// 1. Exactly t local maxima: indices j (1-indexed 2..n-1) where y[j-1] < y[j] > y[j+1]
	//    In 0-indexed: j from 1 to n-2, y[j-1] < y[j] && y[j] > y[j+1]
	// 2. Exactly t-1 local minima: indices j (1-indexed 2..n-1) where y[j-1] > y[j] < y[j+1]
	//    In 0-indexed: j from 1 to n-2, y[j-1] > y[j] && y[j] < y[j+1]
	// 3. No segment parallel to Ox-axis: y[i] != y[i+1] for all i
	// 4. All yi in [1,4]

	// We'll use backtracking/DFS to enumerate all valid sequences.
	// n <= 20, y values 1..4, so 4^20 is too large for brute force.
	// But we can use DP with state tracking.

	// State: position i, last y value, count of maxima so far, count of minima so far, 
	// and whether the previous segment was going up or down (to determine if current point is a local max/min)

	// Actually, let's think about it differently.
	// A local maximum at position j (0-indexed, 1 <= j <= n-2) requires:
	//   y[j-1] < y[j] and y[j] > y[j+1]
	// A local minimum at position j requires:
	//   y[j-1] > y[j] and y[j] < y[j+1]

	// We can do DP where:
	// dp[i][lastY][maxCount][minCount][prevDir] 
	// where prevDir indicates the direction of the last segment (from i-1 to i):
	//   0 = up (y[i] > y[i-1])
	//   1 = down (y[i] < y[i-1])
	//   Note: y[i] != y[i-1] is enforced.

	// When we add a new point at position i+1 with value newY:
	//   newDir = direction from i to i+1
	//   If i >= 1 (meaning we have at least 3 points: i-1, i, i+1), then position i is a local max or min:
	//     - If prevDir was up (y[i] > y[i-1]) and newDir is down (newY < y[i]), then position i is a local max.
	//     - If prevDir was down (y[i] < y[i-1]) and newDir is up (newY > y[i]), then position i is a local min.
	//     - Otherwise (prevDir up and newDir up, or prevDir down and newDir down), position i is neither.

	// Base case: i=0, we just have the first point. No direction yet.
	// i=1: we have two points, direction is determined. No local max/min yet (need 3 points).

	// Let's define:
	// dp[i][lastY][maxCount][minCount][dir] = number of ways
	// where i is the current position (0-indexed, so we've placed i+1 points)
	// lastY is the y-value at position i
	// maxCount is the number of local maxima among positions 1..i-1 (0-indexed)
	// minCount is the number of local minima among positions 1..i-1 (0-indexed)
	// dir is the direction of segment from i-1 to i (only valid for i >= 1)
	//   For i=0, dir can be 0 (dummy)
	//   For i=1, dir is the direction from 0 to 1

	// Transitions:
	// From state (i, lastY, maxCount, minCount, dir) where i >= 1:
	//   For each newY in 1..4 where newY != lastY:
	//     newDir = 0 if newY > lastY, 1 if newY < lastY
	//     newMaxCount = maxCount
	//     newMinCount = minCount
	//     // Check if position i-1 (0-indexed) is a local max or min
	//     // Wait, position i-1 is the previous point. Let me re-index.

	// Let me re-think the indexing.
	// Position 0, 1, 2, ..., n-1
	// Local max/min can only occur at positions 1, 2, ..., n-2
	// A local max at position j (1 <= j <= n-2) depends on y[j-1], y[j], y[j+1]

	// When we are at position i and adding position i+1:
	//   If i >= 1, then position i-1... no wait.
	//   When we add position i+1, we can determine if position i is a local max or min.
	//   Position i is a local max if y[i-1] < y[i] > y[i+1]
	//   Position i is a local min if y[i-1] > y[i] < y[i+1]
	//   This requires i >= 1 (so y[i-1] exists) and we're adding y[i+1].

	// So in DP:
	// State: (i, lastY, maxCount, minCount, dir)
	//   i: current position (0-indexed)
	//   lastY: y[i]
	//   maxCount: number of local maxima at positions 1..i-1 (0-indexed)
	//   minCount: number of local minima at positions 1..i-1 (0-indexed)
	//   dir: direction from i-1 to i (for i >= 1), or 0 for i=0
	//     dir = 0 means y[i] > y[i-1] (up)
	//     dir = 1 means y[i] < y[i-1] (down)

	// Transition from (i, lastY, maxCount, minCount, dir) to (i+1, newY, newMaxCount, newMinCount, newDir):
	//   newY in 1..4, newY != lastY
	//   newDir = 0 if newY > lastY else 1
	//   If i >= 1:
	//     // Position i-1... no, position i is being evaluated now? 
	//     // Wait. When we have positions 0..i, and we add position i+1:
	//     // We can now evaluate position i (since we have y[i-1], y[i], y[i+1])
	//     // But only if i >= 1 (so y[i-1] exists)
	//     // Actually, position i can be a local max/min only if 1 <= i <= n-2
	//     // So when adding position i+1, if i >= 1, we check position i.
	//     
	//     // dir tells us direction from i-1 to i
	//     // newDir tells us direction from i to i+1
	//     if dir == 0 && newDir == 1: // up then down -> local max at position i
	//       newMaxCount = maxCount + 1
	//     else if dir == 1 && newDir == 0: // down then up -> local min at position i
	//       newMinCount = minCount + 1
	//     else:
	//       newMaxCount = maxCount
	//       newMinCount = minCount
	//   Else (i == 0):
	//     newMaxCount = maxCount
	//     newMinCount = minCount

	// Base case: i=0
	//   For each y0 in 1..4:
	//     dp[0][y0][0][0][0] = 1  (dir=0 is dummy)

	// Answer: sum over all states at i=n-1 where maxCount == t and minCount == t-1
	//   dp[n-1][lastY][t][t-1][dir] for all lastY and dir

	// Dimensions:
	// i: 0..n-1 (n <= 20)
	// lastY: 1..4 (4 values)
	// maxCount: 0..t (t <= 10)
	// minCount: 0..t-1 (t-1 <= 9)
	// dir: 0..1 (2 values)

	// Total states: 20 * 4 * 11 * 10 * 2 = 17600, very manageable.

	// Use 5D array or map. Let's use a 5D slice.
	// dp[i][y][mc][mn][d]

	// Initialize
	dp := make([][][][]int, n)
	for i := 0; i < n; i++ {
		dp[i] = make([][][]int, 5) // y: 1..4, index 0 unused
		for y := 0; y < 5; y++ {
			dp[i][y] = make([][]int, t+1) // maxCount: 0..t
			for mc := 0; mc <= t; mc++ {
				dp[i][y][mc] = make([]int, t) // minCount: 0..t-1
