			for mc := 0; mc <= t; mc++ {
				for mn := 0; mn <= t-1; mn++ {
					for d := 0; d <= 1; d++ {
						count := dp[i][lastY][mc][mn][d]
						if count == 0 {
							continue
						}
						for newY := 1; newY <= 4; newY++ {
							if newY == lastY {
								continue
							}
							newDir := 0
							if newY > lastY {
								newDir = 0
							} else {
								newDir = 1
							}
							newMc := mc
							newMn := mn
							if i >= 1 {
								// Check if position i is a local max or min
								if d == 0 && newDir == 1 {
									// up then down -> local max
									newMc = mc + 1
								} else if d == 1 && newDir == 0 {
									// down then up -> local min
									newMn = mn + 1
								}
							}
							if newMc <= t && newMn <= t-1 {
								dp[i+1][newY][newMc][newMn][newDir] += count
							}
						}
					}
				}
			}
		}
	}

	// Answer
	ans := 0
	for lastY := 1; lastY <= 4; lastY++ {
		for d := 0; d <= 1; d++ {
			ans += dp[n-1][lastY][t][t-1][d]
		}
	}

	fmt.Println(ans)
}
